"""Offline validation checks; use a source generated by examples/make_demo.py."""
import argparse
import copy
from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'scripts'))
from common import read_json
from render import overlays, validate

class ProjectChecks(unittest.TestCase):
    def setUp(self):
        self.project = read_json(PROJECT)

    def test_valid_project_and_fonts(self):
        validate(self.project, PROJECT.parent)
        title, captions = overlays(self.project)
        self.assertEqual(title.size, (608, 1080))
        self.assertEqual(len(captions), 4)

    def test_rejects_timeline_gap(self):
        self.project['shots'][1][0] += 0.2
        with self.assertRaises(ValueError):
            validate(self.project, PROJECT.parent)

    def test_rejects_caption_overlap(self):
        self.project['items'][1][0] = 1
        with self.assertRaises(ValueError):
            validate(self.project, PROJECT.parent)

    def test_rejects_blank_bottom(self):
        self.project['shots'][0][3] = -100
        with self.assertRaises(ValueError):
            validate(self.project, PROJECT.parent)

    def test_rejects_nan(self):
        self.project['duration'] = float('nan')
        with self.assertRaises(ValueError):
            validate(self.project, PROJECT.parent)

    def test_rejects_overlong_caption(self):
        self.project['items'][0][3] = '아' * 500
        with self.assertRaises(ValueError):
            overlays(self.project)

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('project')
    args = parser.parse_args()
    PROJECT = Path(args.project).resolve()
    unittest.main(argv=[sys.argv[0]])
